/* Shared product knowledge, maintained by the Bank. No invented fees or eligibility. */
let catalogQuery='',catalogCategory='Semua';
function catalogIcon(){return '<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1m0-15c3-2 6-2 10-1v15c-4-1-7-1-10 1V5Z"/><path d="M5 8h4m-4 4h4m6-4h4m-4 4h4"/></svg>'}
const CATALOG_CATEGORIES=['Tabungan','Giro','Deposito','Kredit konsumtif','Kredit produktif','Kredit program','Layanan lain'];
function catalogType(p){return p.catalog?.category||(/tabungan/i.test(p.name)?'Tabungan':/giro/i.test(p.name)?'Giro':/deposito/i.test(p.name)?'Deposito':/konsumtif/i.test(p.name)?'Kredit konsumtif':/produktif|kur/i.test(p.name)?'Kredit produktif':'Layanan lain')}
function catalogProduct(id){return masters().products.find(p=>p.id===id)}
function catalogStatus(p){const d=p.catalog||{};return d.reviewStatus==='Terverifikasi'&&['summary','requirements','fees','terms','source','effectiveDate'].every(k=>String(d[k]||'').trim())?'Terverifikasi':'Draft'}
function catalogText(value){return value?'<p class="catalog-copy">'+E(value)+'</p>':'<p class="hint">Belum diisi oleh pengelola produk.</p>'}
function catalogSections(p){const d=p.catalog||{};return '<div class="catalog-detail"><div class="catalog-notice"><strong>'+E(catalogStatus(p)==='Terverifikasi'?'Informasi diverifikasi pengelola':'Informasi produk belum diverifikasi')+'</strong><p>Konfirmasi persyaratan, biaya dan ketentuan yang berlaku sebelum menyampaikan penawaran kepada customer.</p></div>'+[['Ringkasan & manfaat',d.summary],['Persyaratan',d.requirements],['Biaya',d.fees],['Ketentuan',d.terms]].map(([t,v])=>'<section><h3>'+t+'</h3>'+catalogText(v)+'</section>').join('')+'<section><h3>Sumber & tanggal berlaku</h3>'+detailFacts([['Sumber / referensi',d.source||'Belum tersedia'],['Berlaku mulai',d.effectiveDate||'Perlu konfirmasi Bank'],['Tanggal dokumen sumber',d.documentDate||'Tidak disebutkan'],['Ditinjau dari situs',d.retrievedAt||'Belum dicatat'],['Pembaruan terakhir',d.updatedAt?fmt(d.updatedAt):'Belum tersedia'],['Diperbarui oleh',d.updatedBy||'Belum tersedia']])+(typeof d.source==='string'&&/^https:\/\/(www\.)?bpdbali\.co\.id\//.test(d.source)?'<a class="button" target="_blank" rel="noopener noreferrer" href="'+E(d.source)+'">Buka sumber resmi Bank</a>':'')+'</section></div>'}
function catalogOpen(id){const p=catalogProduct(id);if(!p||!p.active)return toast('Produk tidak aktif / tidak tersedia.');modal('Katalog Produk · '+p.name,catalogSections(p)+(authUser?.role==='Superadmin'?'<div class="actions">'+btn('Edit informasi produk',"catalogEdit("+E(JSON.stringify(id))+")")+'</div>':''),()=>{});document.querySelector('#form>.actions:last-child')?.remove()}
function catalogEdit(id){if(authUser?.role!=='Superadmin'||journey)return toast('Informasi produk dikelola Superadmin.');const p=catalogProduct(id);if(!p)return;const d=p.catalog||{};modal('Informasi produk · '+p.name,'<p class="hint">Gunakan sumber resmi Bank. Kosongkan informasi yang belum tersedia; jangan mengasumsikan biaya atau persyaratan.</p>'+select('Kategori katalog','category',CATALOG_CATEGORIES,catalogType(p))+area('Ringkasan & manfaat','summary',d.summary||'')+area('Persyaratan','requirements',d.requirements||'')+area('Biaya','fees',d.fees||'')+area('Ketentuan','terms',d.terms||'')+field('Sumber / referensi resmi','source',d.source||'')+field('Berlaku mulai','effectiveDate',d.effectiveDate||'','date')+select('Status informasi','reviewStatus',['Draft','Terverifikasi'],catalogStatus(p)),f=>{
 if(f.reviewStatus==='Terverifikasi'&&(!['summary','requirements','fees','terms','source'].every(k=>f[k]?.trim())||!f.effectiveDate))throw Error('Lengkapi seluruh informasi, sumber resmi, dan tanggal berlaku sebelum verifikasi.');
 const config=clone(db.config),item=config.masters.products.find(x=>x.id===id);item.catalog={...d,...f,updatedAt:now(),updatedBy:actor()};const submit=document.querySelector('#form button.primary');submit.disabled=true;
 api('config',{before:serverBase.config,config,scope:'new'}).then(r=>{applyServer(r);document.querySelector('#modal').close();toast('Informasi produk tersimpan untuk CMS dan mobile')}).catch(e=>{document.querySelector('#formerror').textContent=e.message;submit.disabled=false});return false;
 });}
function catalogScreen(){const products=activeMaster('products'),query=catalogQuery.trim().toLowerCase(),rows=products.filter(p=>(catalogCategory==='Semua'||catalogType(p)===catalogCategory)&&(!query||[p.name,catalogType(p),p.catalog?.summary].join(' ').toLowerCase().includes(query)));
 return titleBlock('Katalog Produk','Panduan produk, persyaratan, biaya, ketentuan, dan sumber informasi Bank.')+'<div class="panel catalog-filters"><label>Cari produk<input type="search" aria-label="Cari produk katalog" placeholder="Nama produk atau manfaat" value="'+E(catalogQuery)+'" onchange="catalogQuery=this.value;renderContent()"></label><label>Kategori<select aria-label="Kategori produk katalog" onchange="catalogCategory=this.value;renderContent()">'+['Semua',...CATALOG_CATEGORIES].map(c=>'<option '+(c===catalogCategory?'selected':'')+'>'+E(c)+'</option>').join('')+'</select></label></div><p class="hint">'+rows.length+' produk sesuai filter. Informasi Draft perlu dilengkapi dan diverifikasi pengelola; katalog tidak menghitung kelayakan atau menyetujui kredit.</p><div class="catalog-grid">'+rows.map(p=>'<article class="panel catalog-card"><div class="recordtop">'+badge(catalogType(p))+badge(catalogStatus(p))+'</div><h2>'+E(p.name)+'</h2>'+catalogText(p.catalog?.summary)+'<div class="actions">'+btn('Lihat detail',"catalogOpen("+E(JSON.stringify(p.id))+")",true)+(authUser?.role==='Superadmin'?btn('Edit informasi',"catalogEdit("+E(JSON.stringify(p.id))+")"):'')+'</div></article>').join('')+'</div>'+(rows.length?'':empty('Tidak ada produk sesuai filter.'));
}
// Show product information inline so opening guidance never loses an unsaved form.
function catalogFormGuidance(){const form=document.querySelector('#form'),input=form?.querySelector('[name="product"]');if(!input||form.querySelector('.catalog-form-guide'))return;const info=document.createElement('details');info.className='catalog-form-guide';const update=()=>{const p=masters().products.find(x=>x.name===input.value&&x.active);info.innerHTML='<summary>Informasi produk: persyaratan, biaya & ketentuan</summary>'+(p?catalogSections(p):'<p class="hint">Pilih produk aktif untuk melihat informasinya.</p>')};input.addEventListener('change',update);input.closest('label')?.after(info);update();}
const catalogModalBefore=modal;
modal=function(...args){const result=catalogModalBefore(...args);catalogFormGuidance();const input=document.querySelector('#form [name="source"]');if(input&&input.tagName==='SELECT'){const note=document.createElement('p');note.className='hint';const update=()=>{const source=activeMaster('sources').find(s=>s.name===input.value);note.textContent=['campaign','digital'].includes(source?.kind)?'Sumber dicatat manual di CRM. Belum menerima Lead otomatis dari campaign atau channel digital.':'';note.hidden=!note.textContent;};input.closest('label')?.after(note);input.addEventListener('change',update);update();}return result;};
const catalogRenderContentBefore=renderContent;
renderContent=function(){if(view==='Katalog Produk'){document.querySelector('#app').innerHTML=catalogScreen();return}catalogRenderContentBefore();if(view==='Pengaturan'&&configTab==='products'&&authUser?.role==='Superadmin')document.querySelectorAll('#app tbody tr').forEach((row,i)=>{const p=masters().products[i];if(p){const cell=row.lastElementChild;const action=document.createElement('button');action.textContent='Informasi produk';action.onclick=()=>catalogEdit(p.id);cell?.append(action)}});};
const catalogRenderBefore=render;
render=function(){catalogRenderBefore();if(!authUser||choosingBranch)return;if(!mobile){const nav=document.querySelector('#nav');if(nav&&!nav.querySelector('[data-catalog]')){const b=document.createElement('button');b.dataset.catalog='1';b.innerHTML=catalogIcon()+'<span class="ui-nav-label">Katalog Produk</span>';b.className=view==='Katalog Produk'?'active':'';b.onclick=()=>go('Katalog Produk');const settings=[...nav.children].find(x=>x.textContent==='Pengaturan');nav.insertBefore(b,settings||null)}}else if(view==='Home'){const grid=document.querySelector('.homemenus');if(grid&&!grid.querySelector('[data-catalog]')){const b=document.createElement('button');b.dataset.catalog='1';b.innerHTML=catalogIcon()+'<strong>Katalog Produk</strong><small>Persyaratan, biaya & ketentuan</small>';b.onclick=()=>go('Katalog Produk');grid.append(b)}}};
if(typeof authUser!=='undefined'&&authUser)render();
